function personalAntigramAnalyze(rows,includeSelected,includeScreens){
 var included=rows.map(function(cell,index){return {cell:cell,index:index};}).filter(function(row){
  var screen=row.cell.type==='screen';
  return row.cell.id!=='Auto'&&(row.index<12||(!screen&&includeSelected)||(screen&&includeScreens));
 });
 var evidence={},ruled=[],confirmation={};
 ANTIGRAM_ANTIGENS.forEach(function(a){
  var positive=included.filter(function(row){return row.cell.antigens[a]==='+'&&/^(w\+|[1-4]\+)$/.test(row.cell.rxn&&row.cell.rxn.ahg||'');}).length;
  var negative=included.filter(function(row){return row.cell.antigens[a]==='0'&&row.cell.rxn&&row.cell.rxn.ahg==='0';}).length;
  confirmation[a]={positive:positive,negative:negative,confirmed:positive>=3&&negative>=3};
 });
 var antiDPattern=confirmation.D.confirmed&&included.filter(function(row){return row.cell.antigens.D==='+'&&row.cell.rxn&&row.cell.rxn.ahg==='0';}).length<2;
 ANTIGRAM_ANTIGENS.forEach(function(a){
  var partner=personalAntigramPairs[a],single=personalAntigramSingleAntigens.includes(a),antiDException=antiDPattern&&(a==='c'||a==='e');
  evidence[a]=included.filter(function(row){
   var cell=row.cell;
   if(!cell.rxn||cell.rxn.ahg!=='0'||cell.antigens[a]!=='+')return false;
   if(single||a==='K'||a==='Lea'||a==='Leb')return true;
   return partner&&(cell.antigens[partner]==='0'||(antiDException&&cell.antigens[partner]==='+'));
  }).map(function(row){return {id:row.cell.id,index:row.index,selected:row.index>=12,screen:row.cell.type==='screen'};});
  if(evidence[a].length>=(antiDException?1:2))ruled.push(a);
 });
 var left=ANTIGRAM_ANTIGENS.filter(function(a){return !ruled.includes(a);});
 var candidates=left.filter(function(a){return !personalAntigramExceptions.includes(a);});
 var review=[];
 var confirmed=candidates.filter(function(a){return confirmation[a].confirmed;});
 var specific=confirmed.length===1?confirmed[0]:null;
 var blockers=candidates.concat(review).filter(function(a){return a!==specific&&!(specific==='e'&&a==='C'&&!confirmation.C.confirmed);});
 if(blockers.length)specific=null;
 var lowIncidence=personalAntigramExceptions.map(function(a){return {antigen:a,crossouts:evidence[a].length};});
 if(specific==='e'&&left.includes('C')&&!confirmation.C.confirmed)lowIncidence.push({antigen:'C',crossouts:evidence.C.length});
 return {evidence:evidence,ruled:ruled,left:left,candidates:candidates,exceptions:left.filter(function(a){return personalAntigramExceptions.includes(a);}),review:review,confirmation:confirmation,specific:specific,blockers:blockers,lowIncidence:lowIncidence};
}
