function personalAntigramHasBlanks(rows,includeSelected,includeScreens){return rows.some(function(cell,i){if(i>=12&&!(cell.type==='screen'?includeScreens:includeSelected))return false;if(cell.id!=='Auto'&&ANTIGRAM_ANTIGENS.some(function(a){return !personalAntigramEntryComplete('antigens',cell.antigens&&cell.antigens[a]);}))return true;return !cell.rxn||!personalAntigramEntryComplete('rxn',cell.rxn.ahg);});}
function togglePersonalAntigramMain(){var rows=personalAntigramCurrent();if(personalAntigramMode==='own'&&(!personalAntigramOwnChecks.qc||!personalAntigramOwnChecks.verified)){showToast('Complete the QC and entry checks before rule-out.',true);return;}if(!personalAntigramMainReveal&&personalAntigramHasBlanks(rows,false,false)){showToast('Fill every blank in Panel A before its rule-out step.',true);return;}personalAntigramMainReveal=!personalAntigramMainReveal;if(!personalAntigramMainReveal){personalAntigramReveal=false;personalAntigramScreenReveal=false;personalAntigramShowAnswers=false;}updatePersonalAntigramResults();}
