function nextPersonalAntigramId(rows,prefix){var max=0;rows.forEach(function(c){var m=String(c.id).match(new RegExp('^'+prefix+' (\\d+)$'));if(m)max=Math.max(max,Number(m[1]));});if(prefix==='Screen'&&notesData&&Array.isArray(notesData.__antigramDeletedScreens))notesData.__antigramDeletedScreens.forEach(function(id){var m=String(id).match(/^Screen (\d+)$/);if(m)max=Math.max(max,Number(m[1]));});return prefix+' '+(max+1);}
