function personalAntigramLoadOcr(){if(window.Tesseract)return Promise.resolve(window.Tesseract);if(personalAntigramOcrLibraryPromise)return personalAntigramOcrLibraryPromise;personalAntigramOcrLibraryPromise=new Promise(function(resolve,reject){var script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@7.0.0/dist/tesseract.min.js';script.onload=function(){resolve(window.Tesseract);};script.onerror=function(){personalAntigramOcrLibraryPromise=null;reject(Error('The text scanner could not load. Check your connection and try again.'));};document.head.appendChild(script);});return personalAntigramOcrLibraryPromise;}
