async function personalAntigramFileCanvas(file){var canvas=document.createElement('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});if(file.type==='application/pdf'||/\.pdf$/i.test(file.name)){var pdfjs=await personalAntigramLoadPdf(),pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise,page=await pdf.getPage(1),raw=page.getViewport({scale:2}),scale=Math.min(1,2800/Math.max(raw.width,raw.height)),viewport=page.getViewport({scale:2*scale});canvas.width=Math.round(viewport.width);canvas.height=Math.round(viewport.height);await page.render({canvasContext:ctx,viewport:viewport}).promise;return canvas;}var image=await createImageBitmap(file),factor=Math.min(1,2800/Math.max(image.width,image.height));canvas.width=Math.round(image.width*factor);canvas.height=Math.round(image.height*factor);ctx.drawImage(image,0,0,canvas.width,canvas.height);image.close();return canvas;}
function personalAntigramOcrWords(data){var words=[];function add(value){if(!value||typeof value.text!=='string'||!value.bbox)return;var b=value.bbox;if(Number.isFinite(b.x0)&&Number.isFinite(b.y0)&&Number.isFinite(b.x1)&&Number.isFinite(b.y1))words.push({text:value.text.trim(),x:(b.x0+b.x1)/2,y:(b.y0+b.y1)/2,left:b.x0,right:b.x1,top:b.y0,bottom:b.y1,confidence:Number(value.confidence)||0});}function walk(value){if(!value)return;if(Array.isArray(value)){value.forEach(walk);return;}if(typeof value!=='object')return;if(typeof value.text==='string'&&value.bbox&&Array.isArray(value.symbols)){add(value);return;}['blocks','paragraphs','lines','words'].forEach(function(key){if(value[key])walk(value[key]);});}if(data&&Array.isArray(data.words)&&data.words.length)data.words.forEach(add);else walk(data&&data.blocks||[]);return words;}
