 var body=visible.map(function(cell){var index=rows.indexOf(cell),screen=cell.type==='screen',zero=answered&&cell.rxn&&cell.rxn.ahg==='0',rowClass=(cell.id==='Auto'?'auto-row ':'')+(screen?'screen-row':'selected-row')+(zero?' ag-export-ahg-zero':'');return '<tr class="'+rowClass+'"><th scope="row">'+escText(cell.id)+'</th>'+antigens.map(function(ag){var value=typeof cell.antigens[ag]==='string'?cell.antigens[ag]:'';var ruled=active&&analysis&&analysis.ruled.includes(ag),cellClass=ruled?'ag-ruled':active&&analysis?'ag-unresolved':'';return '<td class="'+cellClass+'" data-ag="'+escText(ag)+'" data-row="'+index+'">'+(cell.id==='Auto'?'—':escText(value))+'</td>';}).join('')+'<td class="ag-ahg-col">'+escText(cell.rxn&&cell.rxn.ahg||'')+'</td></tr>';}).join('');
