 document.querySelectorAll('[data-ag-ledger]').forEach(function(el){var ag=el.dataset.agLedger,table=el.closest('table'),group=table&&table.classList.contains('antigram-group-selected')?'selected':table&&table.classList.contains('antigram-group-screen')?'screen':'panel',active=group==='panel'?(showMain||showSelected||showScreen||showAnswers):group==='selected'?(showSelected||showScreen||showAnswers):(showScreen||showAnswers),matches=active&&display?display.evidence[ag].filter(function(e){return group==='panel'||(group==='selected'?e.selected&&!e.screen:e.screen);}):[],marks=matches.slice(0,2);el.innerHTML=marks.map(function(e){var source=e.screen?'Screen cell ':e.selected?'Selected cell ':'Panel A cell ';return '<span class="'+(e.screen?'ag-blue':e.selected?'ag-red':'ag-black')+'" title="'+escAttr(source+e.id)+'">'+(personalAntigramSingleAntigens.includes(ag)?'|':'/')+'</span>';}).join('');el.setAttribute('aria-label',marks.map(function(e){return (e.screen?'Screen cell ':e.selected?'Selected cell ':'Panel A cell ')+e.id;}).join(', '));});
