 document.querySelectorAll('[data-ag-title]').forEach(function(el){var table=el.closest('table'),group=table&&table.classList.contains('antigram-group-selected')?'selected':table&&table.classList.contains('antigram-group-screen')?'screen':'panel',active=group==='panel'?(showMain||showSelected||showScreen||showAnswers):group==='selected'?(showSelected||showScreen||showAnswers):(showScreen||showAnswers);styleColumn(el.closest('th'),el.dataset.agTitle,active);});
